public class PublisherTests : IObserver<string>
{
    private readonly List<string> seen = new();
    public void OnNext(string value) => seen.Add(value);
    public void OnError(Exception e) { }
    public void OnCompleted() { }
    [Fact] public void PublishesOnce()
    {
        new Publisher(this).Change("x");   // install the test object itself
        Assert.Equal(new[] { "x" }, seen);
    }
}
